import SwiftUI

struct Note: Identifiable {
    let id = UUID()
    let title: String
}

struct ContentView: View {
    @State private var notes: [Note] = []
    @State private var title = ""
    var body: some View {
        NavigationStack {
            VStack {
                Text("Notes")
                if notes.isEmpty { Text("No notes") }
                List(notes) { note in
                    NavigationLink(note.title) { Text(note.title) }
                }
                TextField("New note", text: $title)
                Button("Add") {
                    if !title.trimmingCharacters(in: .whitespaces).isEmpty {
                        notes.append(Note(title: title))
                        title = ""
                    }
                }
            }
        }
    }
}
